276	// writeCommittedMain writes metadata entries to the /main ref.
277	// This includes session metadata and prompts — but NOT the raw transcript
278	// (raw_transcript) or content hash (raw_transcript_hash.txt), which go to /full/current.
279	// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
280	func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
281		refName := plumbing.ReferenceName(paths.V2MainRefName)
282		if err := s.ensureRef(ctx, refName); err != nil {
283			return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
284		}
285	
286		parentHash, rootTreeHash, err := s.GetRefState(refName)
287		if err != nil {
288			return 0, err
289		}
290	
291		basePath := opts.CheckpointID.Path() + "/"
292		checkpointPath := opts.CheckpointID.Path()
293	
294		// Read existing entries at this checkpoint's shard path
295		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
296		if err != nil {
297			return 0, err
298		}
299	
300		// Build main session entries (metadata, prompts — no transcript or content hash)
301		sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
302		if err != nil {
303			return 0, err
304		}
305	
306		// Splice entries into root tree
307		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
308		if err != nil {
309			return 0, err
310		}
311	
312		commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
313		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
314			return 0, err
315		}
316		return sessionIndex, nil
317	}
