473	// writeCompactTranscriptHash computes and writes the SHA-256 hash of the compact transcript.
474	func (s *V2GitStore) writeCompactTranscriptHash(compactTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
475		hash := fmt.Sprintf("sha256:%x", sha256.Sum256(compactTranscript))
476		blobHash, err := CreateBlobFromContent(s.repo, []byte(hash))
477		if err != nil {
478			return err
479		}
480		entries[sessionPath+paths.CompactTranscriptHashFileName] = object.TreeEntry{
481			Name: sessionPath + paths.CompactTranscriptHashFileName,
482			Mode: filemode.Regular,
483			Hash: blobHash,
484		}
485		return nil
486	}
