488	// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
489	// Transcripts accumulate across checkpoints — each write splices into the existing
490	// tree. Generation metadata (generation.json) at the tree root is updated on every
491	// write with the new checkpoint ID and timestamps.
492	//
493	// sessionIndex is the session slot (0-based), determined by the caller to stay
494	// consistent with the /main ref's session numbering.
495	// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
496	func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
497		transcript := opts.Transcript
498	
499		// TranscriptPath fallback: data read from disk is an untrusted source,
500		// so we redact it here. The in-memory path (opts.Transcript) is already
501		// pre-redacted by the caller.
502		if transcript.Len() == 0 && opts.TranscriptPath != "" {
503			rawData, readErr := os.ReadFile(opts.TranscriptPath)
504			if readErr != nil {
505				rawData = nil
506			}
507			if len(rawData) > 0 {
508				redacted, redactErr := redact.JSONLBytes(rawData)
509				if redactErr != nil {
510					return fmt.Errorf("failed to redact transcript from file: %w", redactErr)
511				}
512				transcript = redacted
513			}
514		}
515		if transcript.Len() == 0 {
516			return nil // No transcript to write
517		}
518	
519		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
520		if err := s.ensureRef(ctx, refName); err != nil {
521			return fmt.Errorf("failed to ensure /full/current ref: %w", err)
522		}
523	
524		parentHash, rootTreeHash, err := s.GetRefState(refName)
525		if err != nil {
526			return err
527		}
528	
529		basePath := opts.CheckpointID.Path() + "/"
530		checkpointPath := opts.CheckpointID.Path()
531		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
532	
533		// Read existing entries at this checkpoint's shard path
534		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
535		if err != nil {
536			return err
537		}
538	
539		// Clear existing entries at this session path before writing new ones
540		for key := range entries {
541			if strings.HasPrefix(key, sessionPath) {
542				delete(entries, key)
543			}
544		}
545	
546		if err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, nil, sessionPath, entries); err != nil {
547			return err
548		}
549	
550		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript.Bytes()))
551		if err := s.writeContentHashFromPrecompute(contentHash, nil, sessionPath, entries); err != nil {
552			return err
553		}
554	
555		// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
556		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
557		if err != nil {
558			return err
559		}
560	
561		commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
562		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
563			return err
564		}
565	
566		// Check if rotation is needed after successful write.
567		// Count checkpoints by walking the tree (no generation.json on /full/current).
568		checkpointCount, countErr := s.CountCheckpointsInTree(newTreeHash)
569		if countErr != nil {
570			logging.Warn(ctx, "failed to count checkpoints for rotation check",
571				slog.String("error", countErr.Error()),
572			)
573			return nil
574		}
575		if checkpointCount >= s.maxCheckpoints() {
576			if rotErr := s.rotateGeneration(ctx); rotErr != nil {
577				logging.Warn(ctx, "generation rotation failed",
578					slog.String("error", rotErr.Error()),
579					slog.Int("checkpoint_count", checkpointCount),
580				)
581				// Non-fatal: rotation failure doesn't invalidate the write
582			}
583		}
584	
585		return nil
586	}
