588	// writeTranscriptBlobs writes pre-redacted, chunked transcript blobs to entries.
589	// When precomputed is non-nil, reuses its chunk blob hashes and skips both
590	// ChunkTranscript and CreateBlobFromContent.
591	func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript redact.RedactedBytes, agentType types.AgentType, precomputed *PrecomputedTranscriptBlobs, sessionPath string, entries map[string]object.TreeEntry) error {
592		var chunkHashes []plumbing.Hash
593		if precomputed != nil {
594			chunkHashes = precomputed.ChunkHashes
595		} else {
596			chunks, err := chunkTranscript(ctx, transcript.Bytes(), agentType)
597			if err != nil {
598				return fmt.Errorf("failed to chunk transcript: %w", err)
599			}
600			chunkHashes = make([]plumbing.Hash, len(chunks))
601			for i, chunk := range chunks {
602				h, err := CreateBlobFromContent(s.repo, chunk)
603				if err != nil {
604					return err
605				}
606				chunkHashes[i] = h
607			}
608		}
609	
610		for i, blobHash := range chunkHashes {
611			chunkPath := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
612			entries[chunkPath] = object.TreeEntry{
613				Name: chunkPath,
614				Mode: filemode.Regular,
615				Hash: blobHash,
616			}
617		}
618	
619		return nil
620	}
