661	// UpdateSummary persists an AI-generated summary into the latest session's
662	// metadata on the v2 /main ref. Mirrors GitStore.UpdateSummary for v1.
663	func (s *V2GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
664		if err := ctx.Err(); err != nil {
665			return err //nolint:wrapcheck // Propagating context cancellation
666		}
667	
668		refName := plumbing.ReferenceName(paths.V2MainRefName)
669		parentHash, rootTreeHash, err := s.GetRefState(refName)
670		if err != nil {
671			return ErrCheckpointNotFound
672		}
673	
674		basePath := checkpointID.Path() + "/"
675		checkpointPath := checkpointID.Path()
676		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
677		if err != nil {
678			return err
679		}
680	
681		rootMetadataPath := basePath + paths.MetadataFileName
682		entry, exists := entries[rootMetadataPath]
683		if !exists {
684			return ErrCheckpointNotFound
685		}
686	
687		cpSummary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
688		if err != nil {
689			return fmt.Errorf("failed to read checkpoint summary: %w", err)
690		}
691		if len(cpSummary.Sessions) == 0 {
692			return ErrCheckpointNotFound
693		}
694	
695		latestIndex := len(cpSummary.Sessions) - 1
696		sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
697		sessionEntry, exists := entries[sessionMetadataPath]
698		if !exists {
699			return fmt.Errorf("session metadata not found at index %d", latestIndex)
700		}
701	
702		metadata, err := readJSONFromBlob[CommittedMetadata](s.repo, sessionEntry.Hash)
703		if err != nil {
704			return fmt.Errorf("failed to read session metadata: %w", err)
705		}
706		metadata.Summary = redactSummary(summary)
707	
708		metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
709		if err != nil {
710			return fmt.Errorf("failed to marshal metadata: %w", err)
711		}
712		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
713		if err != nil {
714			return fmt.Errorf("failed to create metadata blob: %w", err)
715		}
716		entries[sessionMetadataPath] = object.TreeEntry{
717			Name: sessionMetadataPath,
718			Mode: filemode.Regular,
719			Hash: metadataHash,
720		}
721	
722		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, checkpointID, basePath, entries)
723		if err != nil {
724			return err
725		}
726	
727		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
728		commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, metadata.SessionID)
729		return s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
730	}
