156	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, out io.Writer, prefix string, force bool) error {
157		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
158		if err != nil {
159			return fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
160		}
161	
162		// Already in v2 — when not forcing, check if any aspect of sessions are missing and backfill
163		if existing != nil && !force {
164			repaired, repairErr := repairPartialV2Checkpoint(ctx, repo, v1Store, v2Store, info, existing)
165			if repairErr != nil {
166				return repairErr
167			}
168	
169			currentV2, readCurrentErr := v2Store.ReadCommitted(ctx, info.CheckpointID)
170			if readCurrentErr != nil {
171				return fmt.Errorf("failed to re-read v2 checkpoint %s: %w", info.CheckpointID, readCurrentErr)
172			}
173			if currentV2 == nil {
174				return fmt.Errorf("v2 checkpoint %s disappeared during migration", info.CheckpointID)
175			}
176	
177			backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, currentV2, out, prefix)
178			if errors.Is(backfillErr, errAlreadyMigrated) && repaired {
179				fmt.Fprintf(out, "%s repaired partial v2 checkpoint state\n", prefix)
180				return nil
181			}
182			if errors.Is(backfillErr, errTranscriptNotGeneratable) && repaired {
183				fmt.Fprintf(out, "%s repaired partial v2 checkpoint state (compact transcript not generated)\n", prefix)
184				return nil
185			}
186			return backfillErr
187		}
188	
189		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
190		if err != nil {
191			return fmt.Errorf("failed to read v1 summary: %w", err)
192		}
193		if summary == nil {
194			return fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
195		}
196	
197		compactFailed := false
198		shouldCopyTaskMetadata := false
199	
200		for sessionIdx := range len(summary.Sessions) {
201			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
202			if readErr != nil {
203				return fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
204			}
205			if content.Metadata.IsTask {
206				shouldCopyTaskMetadata = true
207			}
208	
209			opts := buildMigrateWriteOpts(content, info)
210	
211			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
212			if compacted != nil {
213				opts.CompactTranscript = compacted
214				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
215			} else if len(content.Transcript) > 0 {
216				compactFailed = true
217			}
218	
219			if writeErr := v2Store.WriteCommitted(ctx, opts); writeErr != nil {
220				return fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
221			}
222		}
223	
224		// Copy task metadata trees from v1 to v2 /full/current
225		if shouldCopyTaskMetadata {
226			if taskErr := copyTaskMetadataToV2(ctx, repo, v1Store, v2Store, info.CheckpointID, summary); taskErr != nil {
227				logging.Warn(ctx, "failed to copy task metadata to v2",
228					slog.String("checkpoint_id", string(info.CheckpointID)),
229					slog.String("error", taskErr.Error()),
230				)
231			}
232		}
233	
234		if compactFailed {
235			fmt.Fprintf(out, "%s done (compact transcript not generated)\n", prefix)
236		} else {
237			fmt.Fprintf(out, "%s done\n", prefix)
238		}
239	
240		return nil
241	}
242	
243	func repairPartialV2Checkpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary) (bool, error) {
244		repaired := false
245	
246		// Spot-check already present sessions: ensure required /full/current artifacts exist.
247		existingSessionCount := len(v2Summary.Sessions)
248		for sessionIdx := range existingSessionCount {
249			ok, checkErr := hasCurrentFullSessionArtifacts(repo, v2Store, info.CheckpointID, sessionIdx)
250			if checkErr != nil {
251				return false, fmt.Errorf("failed to check v2 session %d artifacts: %w", sessionIdx, checkErr)
252			}
253			if ok {
254				continue
255			}
256	
257			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
258			if readErr != nil {
259				return false, fmt.Errorf("failed to read v1 session %d while repairing v2: %w", sessionIdx, readErr)
260			}
261	
262			updateOpts := checkpoint.UpdateCommittedOptions{
263				CheckpointID: info.CheckpointID,
264				SessionID:    content.Metadata.SessionID,
265				// content.Transcript was read from v1 checkpoint storage and is
266				// already redacted at write time.
267				Transcript: redact.AlreadyRedacted(content.Transcript),
268				Prompts:    checkpoint.SplitPromptContent(content.Prompts),
269				Agent:      content.Metadata.Agent,
270			}
271			if compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata); compacted != nil {
272				updateOpts.CompactTranscript = compacted
273			}
274	
275			if updateErr := v2Store.UpdateCommitted(ctx, updateOpts); updateErr != nil {
276				return false, fmt.Errorf("failed to repair v2 session %d: %w", sessionIdx, updateErr)
277			}
278			repaired = true
279		}
280	
281		return repaired, nil
282	}
283	
284	func hasCurrentFullSessionArtifacts(repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int) (bool, error) {
285		_, rootTreeHash, err := v2Store.GetRefState(plumbing.ReferenceName(paths.V2FullCurrentRefName))
286		if err != nil {
287			return false, nil //nolint:nilerr // Missing /full/current ref means required artifacts are absent.
288		}
289	
290		rootTree, err := repo.TreeObject(rootTreeHash)
291		if err != nil {
292			return false, fmt.Errorf("failed to read /full/current tree: %w", err)
293		}
294	
295		sessionPath := fmt.Sprintf("%s/%d", cpID.Path(), sessionIdx)
296		sessionTree, err := rootTree.Tree(sessionPath)
297		if err != nil {
298			return false, nil //nolint:nilerr // Missing session path means artifacts are absent, not a hard error.
299		}
300	
301		hasTranscript := false
302		for _, entry := range sessionTree.Entries {
303			if entry.Name == paths.V2RawTranscriptFileName || strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+".") {
304				hasTranscript = true
305				break
306			}
307		}
308		if !hasTranscript {
309			return false, nil
310		}
311	
312		if _, err := sessionTree.File(paths.V2RawTranscriptHashFileName); err != nil {
313			return false, nil //nolint:nilerr // Missing content hash indicates incomplete /full/current artifacts.
314		}
315	
316		return true, nil
317	}
318	
319	// backfillCompactTranscripts checks sessions in an already-migrated v2 checkpoint
320	// for missing transcript.jsonl and attempts to generate + write them from v1 data.
321	// Returns errAlreadyMigrated if all sessions already have compact transcripts.
322	func backfillCompactTranscripts(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary, out io.Writer, prefix string) error {
323		// Find sessions missing transcript.jsonl
324		var needsBackfill []int
325		for i, session := range v2Summary.Sessions {
326			if session.Transcript == "" {
327				needsBackfill = append(needsBackfill, i)
328			}
329		}
330	
331		if len(needsBackfill) == 0 {
332			return errAlreadyMigrated
333		}
334	
335		backfilled := 0
336		var lastAgent string
337	
338		for _, sessionIdx := range needsBackfill {
339			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
340			if readErr != nil {
341				logging.Warn(ctx, "transcript.jsonl backfill: could not read v1 session",
342					slog.String("checkpoint_id", string(info.CheckpointID)),
343					slog.Int("session_index", sessionIdx),
344					slog.String("error", readErr.Error()),
345				)
346				continue
347			}
348	
349			if content.Metadata.Agent != "" {
350				lastAgent = string(content.Metadata.Agent)
351			}
352	
353			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
354			if compacted == nil {
355				// tryCompactTranscript already logs for no-agent and compact-error cases;
356				// log the empty-transcript case here.
357				if len(content.Transcript) == 0 {
358					logging.Warn(ctx, "transcript.jsonl backfill: empty transcript in v1",
359						slog.String("checkpoint_id", string(info.CheckpointID)),
360						slog.Int("session_index", sessionIdx),
361					)
362				}
363				continue
364			}
365	
366			updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
367				CheckpointID:      info.CheckpointID,
368				SessionID:         content.Metadata.SessionID,
369				CompactTranscript: compacted,
370			})
371			if updateErr != nil {
372				logging.Warn(ctx, "transcript.jsonl backfill: failed to write to v2",
373					slog.String("checkpoint_id", string(info.CheckpointID)),
374					slog.Int("session_index", sessionIdx),
375					slog.String("error", updateErr.Error()),
376				)
377				continue
378			}
379	
380			backfilled++
381		}
382	
383		if backfilled == 0 {
384			if lastAgent != "" {
385				return fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
386			}
387			return fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
388		}
389	
390		fmt.Fprintf(out, "%s added transcript.jsonl for %d session(s)\n", prefix, backfilled)
391	
392		return nil
393	}
394	
395	func buildMigrateWriteOpts(content *checkpoint.SessionContent, info checkpoint.CommittedInfo) checkpoint.WriteCommittedOptions {
396		m := content.Metadata
397	
398		prompts := checkpoint.SplitPromptContent(content.Prompts)
399	
400		return checkpoint.WriteCommittedOptions{
401			CheckpointID: info.CheckpointID,
402			SessionID:    m.SessionID,
403			Strategy:     m.Strategy,
404			Branch:       m.Branch,
405			// content.Transcript comes from persisted checkpoint storage and is
406			// already redacted.
407			Transcript:                  redact.AlreadyRedacted(content.Transcript),
408			Prompts:                     prompts,
409			FilesTouched:                m.FilesTouched,
410			CheckpointsCount:            m.CheckpointsCount,
