467	// computeCompactOffset determines the transcript.jsonl line offset for a checkpoint
468	// by comparing a full compact (startLine=0) against the scoped compact. The difference
469	// is the number of compact lines before this checkpoint's data.
470	func computeCompactOffset(ctx context.Context, fullTranscript, fullCompact []byte, m checkpoint.CommittedMetadata) int {
471		startLine := m.GetTranscriptStart()
472		if startLine == 0 || len(fullTranscript) == 0 || m.Agent == "" {
473			return 0
474		}
475	
476		if len(fullCompact) == 0 {
477			return 0
478		}
479	
480		// fullTranscript is read from persisted checkpoint storage and already redacted.
481		scopedCompact, err := compact.Compact(redact.AlreadyRedacted(fullTranscript), compact.MetadataFields{
482			Agent:      string(m.Agent),
483			CLIVersion: versioninfo.Version,
484			StartLine:  startLine,
485		})
486		if err != nil {
487			logging.Warn(ctx, "compact transcript offset calculation failed during migration",
488				slog.String("checkpoint_id", string(m.CheckpointID)),
489				slog.String("agent", string(m.Agent)),
490				slog.String("error", err.Error()),
491			)
492			return 0
493		}
494		if len(scopedCompact) == 0 {
495			return 0
496		}
497	
498		fullLines := bytes.Count(fullCompact, []byte{'\n'})
499		scopedLines := bytes.Count(scopedCompact, []byte{'\n'})
500		offset := fullLines - scopedLines
501		if offset < 0 {
502			logging.Warn(ctx, "compact transcript offset was negative during migration, defaulting to 0",
503				slog.String("checkpoint_id", string(m.CheckpointID)),
504				slog.Int("full_lines", fullLines),
505				slog.Int("scoped_lines", scopedLines),
506			)
507			return 0
508		}
509		return offset
510	}
