583	func spliceTasksTreeToV2(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int, tasksTreeHash plumbing.Hash) error {
584		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
585		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
586		if err != nil {
587			return fmt.Errorf("failed to get v2 ref state: %w", err)
588		}
589		incomingTasksTree, err := repo.TreeObject(tasksTreeHash)
590		if err != nil {
591			return fmt.Errorf("failed to read tasks tree: %w", err)
592		}
593	
594		shardPrefix := string(cpID[:2])
595		shardSuffix := string(cpID[2:])
596		sessionDir := strconv.Itoa(sessionIdx)
597	
598		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
599			[]string{shardPrefix, shardSuffix, sessionDir, "tasks"},
600			incomingTasksTree.Entries,
601			checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting},
602		)
603		if err != nil {
604			return fmt.Errorf("tree surgery failed: %w", err)
605		}
606	
607		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
608			fmt.Sprintf("Add task metadata for %s\n", cpID),
609			"Entire Migration", "migration@entire.dev")
610		if err != nil {
611			return fmt.Errorf("failed to create commit: %w", err)
612		}
613	
614		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
615			return fmt.Errorf("failed to update ref %s: %w", refName, err)
616		}
617		return nil
618	}
