775	// mergeFilesTouched combines two file lists, removing duplicates.
776	// All paths are normalized to forward slashes for platform-agnostic storage.
777	func mergeFilesTouched(existing, additional []string) []string {
778		seen := make(map[string]bool)
779		var result []string
780	
781		for _, f := range existing {
782			f = filepath.ToSlash(f)
783			if !seen[f] {
784				seen[f] = true
785				result = append(result, f)
786			}
787		}
788		for _, f := range additional {
789			f = filepath.ToSlash(f)
790			if !seen[f] {
791				seen[f] = true
792				result = append(result, f)
793			}
794		}
795	
796		sort.Strings(result)
797		return result
798	}
