242	// ReadSessionContent reads a session's metadata and prompts from the v2 /main ref,
243	// and the raw transcript (raw_transcript) from /full/* refs (current + archived generations).
244	// This is the v2 equivalent of GitStore.ReadSessionContent — it reads the raw agent
245	// transcript, not the compact transcript.jsonl. Used by resume and RestoreLogsOnly.
246	// Returns ErrNoTranscript if the session exists but no raw transcript is available.
247	// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
248	func (s *V2GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
249		if err := ctx.Err(); err != nil {
250			return nil, err //nolint:wrapcheck // Propagating context cancellation
251		}
252	
253		refName := plumbing.ReferenceName(paths.V2MainRefName)
254		_, rootTreeHash, err := s.GetRefState(refName)
255		if err != nil {
256			return nil, ErrCheckpointNotFound
257		}
258	
259		rootTree, err := s.repo.TreeObject(rootTreeHash)
260		if err != nil {
261			return nil, ErrCheckpointNotFound
262		}
263	
264		cpTree, err := rootTree.Tree(checkpointID.Path())
265		if err != nil {
266			return nil, ErrCheckpointNotFound
267		}
268	
269		sessionDir := strconv.Itoa(sessionIndex)
270		sessionTree, err := cpTree.Tree(sessionDir)
271		if err != nil {
272			return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
273		}
274	
275		result := &SessionContent{}
276	
277		if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
278			if content, contentErr := metadataFile.Contents(); contentErr == nil {
279				if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
280					return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
281				}
282			}
283		}
284	
285		if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
286			if content, contentErr := file.Contents(); contentErr == nil {
287				result.Prompts = content
288			}
289		}
290	
291		transcript, transcriptErr := s.readTranscriptFromFullRefs(ctx, checkpointID, sessionIndex, result.Metadata.Agent)
292		if transcriptErr != nil {
293			return nil, fmt.Errorf("failed to read transcript from /full/* refs: %w", transcriptErr)
294		}
295		if len(transcript) == 0 {
296			return nil, ErrNoTranscript
297		}
298		result.Transcript = transcript
299	
300		return result, nil
301	}
