303	// readTranscriptFromFullRefs reads the raw transcript for a checkpoint session
304	// by searching /full/current first, then archived generations in reverse order.
305	// If not found locally, attempts to discover and fetch remote /full/* refs.
306	func (s *V2GitStore) readTranscriptFromFullRefs(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, agentType types.AgentType) ([]byte, error) {
307		if err := ctx.Err(); err != nil {
308			return nil, err //nolint:wrapcheck // Propagating context cancellation
309		}
310	
311		sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)
312	
313		// Search locally first
314		transcript, err := s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
315		if err == nil && len(transcript) > 0 {
316			return transcript, nil
317		}
318	
319		archived, err := s.ListArchivedGenerations()
320		if err != nil {
321			return nil, err
322		}
323		for i := len(archived) - 1; i >= 0; i-- {
324			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + archived[i])
325			transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
326			if err == nil && len(transcript) > 0 {
327				return transcript, nil
328			}
329		}
330	
331		// Not found locally — try fetching remote /full/* refs
332		if fetchErr := s.fetchRemoteFullRefs(ctx); fetchErr != nil {
333			logging.Debug(ctx, "failed to fetch remote /full/* refs",
334				slog.String("error", fetchErr.Error()),
335			)
336			return nil, nil
337		}
338	
339		// Search newly fetched refs only
340		newArchived, err := s.ListArchivedGenerations()
341		if err != nil {
342			return nil, nil //nolint:nilerr // Best-effort: fetch-on-demand failure shouldn't block resume
343		}
344		existingSet := make(map[string]bool, len(archived))
345		for _, a := range archived {
346			existingSet[a] = true
347		}
348		for i := len(newArchived) - 1; i >= 0; i-- {
349			if existingSet[newArchived[i]] {
350				continue
351			}
352			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + newArchived[i])
353			transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
354			if err == nil && len(transcript) > 0 {
355				return transcript, nil
356			}
357		}
358	
359		// Also retry /full/current in case it was updated by the fetch
360		transcript, err = s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
361		if err == nil && len(transcript) > 0 {
362			return transcript, nil
363		}
364	
365		return nil, nil
366	}
