368	// fetchRemoteFullRefs discovers and fetches /full/* refs from the configured
369	// FetchRemote that aren't local.
370	func (s *V2GitStore) fetchRemoteFullRefs(ctx context.Context) error {
371		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
372		defer cancel()
373	
374		lsCmd := exec.CommandContext(ctx, "git", "ls-remote", s.FetchRemote, paths.V2FullRefPrefix+"*")
375		output, err := lsCmd.Output()
376		if err != nil {
377			return fmt.Errorf("ls-remote failed: %w", err)
378		}
379	
380		var refSpecs []string
381		for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
382			if line == "" {
383				continue
384			}
385			parts := strings.Fields(line)
386			if len(parts) < 2 {
387				continue
388			}
389			remoteRefName := parts[1]
390	
391			// Skip refs that already exist locally
392			if _, refErr := s.repo.Reference(plumbing.ReferenceName(remoteRefName), true); refErr == nil {
393				continue
394			}
395	
396			refSpecs = append(refSpecs, fmt.Sprintf("+%s:%s", remoteRefName, remoteRefName))
397		}
398	
399		if len(refSpecs) == 0 {
400			return nil
401		}
402	
403		args := append([]string{"fetch", "--no-tags", s.FetchRemote}, refSpecs...)
404		fetchCmd := exec.CommandContext(ctx, "git", args...)
405		if fetchOutput, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
406			return fmt.Errorf("fetch failed: %s", fetchOutput)
407		}
408	
409		return nil
410	}
