412	// readTranscriptFromRef reads the raw transcript from a specific /full/* ref.
413	// Follows the same chunking convention as readTranscriptFromTree in committed.go:
414	// chunk 0 is the base file (raw_transcript), chunks 1+ are raw_transcript.001, .002, etc.
415	// When chunk files exist, all chunks (including chunk 0) are reassembled using
416	// agent-aware reassembly via agent.ReassembleTranscript.
417	func (s *V2GitStore) readTranscriptFromRef(refName plumbing.ReferenceName, sessionPath string, agentType types.AgentType) ([]byte, error) {
418		_, rootTreeHash, err := s.GetRefState(refName)
419		if err != nil {
