423		rootTree, err := s.repo.TreeObject(rootTreeHash)
424		if err != nil {
425			return nil, fmt.Errorf("failed to read tree: %w", err)
426		}
427	
428		sessionTree, err := rootTree.Tree(sessionPath)
429		if err != nil {

428		sessionTree, err := rootTree.Tree(sessionPath)
429		if err != nil {
430			return nil, fmt.Errorf("session path %s not found: %w", sessionPath, err)
431		}
