150	func (s *GitStore) flattenCheckpointEntries(rootTreeHash plumbing.Hash, checkpointPath string) (map[string]object.TreeEntry, error) {
151		entries := make(map[string]object.TreeEntry)
152		if rootTreeHash == plumbing.ZeroHash {
153			return entries, nil
154		}
155	
156		rootTree, err := s.repo.TreeObject(rootTreeHash)
157		if err != nil {
158			if errors.Is(err, plumbing.ErrObjectNotFound) {
159				return entries, nil // Tree doesn't exist yet
160			}
