// cleanupV1TranscriptFiles removes legacy v1-named transcript files (full.jsonl,
// full.jsonl.*, content_hash.txt) from /full/current. Older CLI versions wrote
// these before the rename to raw_transcript; they are inert but waste space.
// Best-effort: failures are logged and do not block migration.
func cleanupV1TranscriptFiles(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionCount int) {
	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
	parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
	if err != nil {
		return // /full/current doesn't exist yet — nothing to clean
	}

	checkpointPath := cpID.Path()
	basePath := checkpointPath + "/"

	entries, err := checkpoint.NewGitStore(repo).FlattenCheckpointEntries(rootTreeHash, checkpointPath)
	if err != nil {
		return
	}

	changed := false
	for sessionIdx := range sessionCount {
		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIdx)
		v1TranscriptPath := sessionPath + paths.TranscriptFileName
		v1HashPath := sessionPath + paths.ContentHashFileName

		for key := range entries {
			switch {
			case key == v1TranscriptPath,
				strings.HasPrefix(key, v1TranscriptPath+"."),
				key == v1HashPath:
				delete(entries, key)
				changed = true
			}
		}
	}

	if !changed {
		return
	}

	newTreeHash, err := checkpoint.NewGitStore(repo).SpliceCheckpointSubtree(ctx, rootTreeHash, cpID, basePath, entries)
	if err != nil {
		logging.Warn(ctx, "v1 transcript cleanup: tree surgery failed",
			slog.String("checkpoint_id", string(cpID)),
			slog.String("error", err.Error()),
		)
		return
	}

	commitHash, err := checkpoint.CreateCommit(ctx, repo, newTreeHash, parentHash,
		fmt.Sprintf("Clean up v1 transcript files for %s\n", cpID),
		"Entire Migration", "migration@entire.dev")
	if err != nil {
		logging.Warn(ctx, "v1 transcript cleanup: commit failed",
			slog.String("checkpoint_id", string(cpID)),
			slog.String("error", err.Error()),
		)
		return
	}

	if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
		logging.Warn(ctx, "v1 transcript cleanup: ref update failed",
			slog.String("checkpoint_id", string(cpID)),
			slog.String("error", err.Error()),
		)
	}
}

